 function refreshAnnouncementPfps(){if(!latestAnnouncements)return;const cards=[...announcementList.querySelectorAll('.announcement-card')];cards.forEach((card,index)=>{const data=latestAnnouncements.docs[index]?.data();if(!data)return;let avatar=card.querySelector('.announcement-avatar');if(!avatar){avatar=document.createElement('span');avatar.className='announcement-avatar';card.insertBefore(avatar,card.querySelector('.announcement-author'))}fillAvatar(avatar,data.authorUid,'🌙')})}
