 function drawPfpAccess(){pfpAccessList.replaceChildren(...pfpAccessRecords.map(record=>{const row=document.createElement('div'),text=document.createElement('span'),remove=button('REVOKE','admin-remove');row.className='pfp-access-row';text.textContent=(record.name||'unnamed creature')+' — '+record.id;remove.onclick=async()=>{remove.disabled=true;try{const batch=firestore.writeBatch(db);batch.delete(firestore.doc(db,'pfpAccess',record.id));batch.delete(firestore.doc(db,'profiles',record.id));await batch.commit()}catch(error){console.error(error);remove.disabled=false}};row.append(text,remove);return row}));if(!pfpAccessRecords.length)pfpAccessList.textContent='no custom picture passes granted.'}
