 function shrinkPfp(file){return new Promise((resolve,reject)=>{if(!file||file.size>5*1024*1024){reject(new Error('Choose an image under 5 MB.'));return}if(!['image/png','image/jpeg','image/webp'].includes(file.type)){reject(new Error('Use a PNG, JPEG, or WebP image.'));return}const url=URL.createObjectURL(file),image=new Image();image.onload=()=>{URL.revokeObjectURL(url);const size=Math.min(image.naturalWidth,image.naturalHeight),left=(image.naturalWidth-size)/2,top=(image.naturalHeight-size)/2,canvas=document.createElement('canvas');canvas.width=128;canvas.height=128;const context=canvas.getContext('2d');context.drawImage(image,left,top,size,size,0,0,128,128);let quality=.82,data=canvas.toDataURL('image/jpeg',quality);while(data.length>68000&&quality>.35){quality-=.1;data=canvas.toDataURL('image/jpeg',quality)}if(data.length>68000)reject(new Error('That image could not be compressed enough.'));else resolve(data)};image.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('That image could not be opened.'))};image.src=url})}
