 function shrinkChatImage(file){return new Promise((resolve,reject)=>{if(!file||file.size>8*1024*1024){reject(new Error('image too enormous'));return}if(!['image/png','image/jpeg','image/webp'].includes(file.type)){reject(new Error('forbidden-file'));return}const url=URL.createObjectURL(file),image=new Image();image.onload=()=>{URL.revokeObjectURL(url);const scale=Math.min(1,640/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));const context=canvas.getContext('2d');context.drawImage(image,0,0,canvas.width,canvas.height);let quality=.72,data=canvas.toDataURL('image/jpeg',quality);while(data.length>140000&&quality>.32){quality-=.08;data=canvas.toDataURL('image/jpeg',quality)}if(data.length>140000)reject(new Error('image too enormous'));else resolve(data)};image.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('forbidden-file'))};image.src=url})}
